"use strict";

/**
 * Sphere Farm Panel: the Day World's ground layer.
 * Guards: (a) the dataset is complete and every window carries a
 * source that exists in the registry — a window with no source
 * behind it does not ship; (b) the date logic answers plainly and
 * correctly against fixed fixtures in both founding counties;
 * (c) the Codex moon layer is never generated by the module and,
 * when a caller supplies it, stays under its own label.
 */

const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const test = require("node:test");

const root = path.resolve(__dirname, "..");
const data = JSON.parse(
  fs.readFileSync(path.join(root, "docs/assets/data/farm-western-wa.json"), "utf8")
);
const panel = require(path.join(root, "docs/assets/js/sphere-farm-panel.js"));

const FROST_CLASSES = new Set(["hardy", "semi-hardy", "tender", "very-tender"]);
const sourceIds = new Set(data.sources.map(s => s.id));

function assertSourced(part, label) {
  assert.ok(part, `${label} missing`);
  assert.ok(Array.isArray(part.sources) && part.sources.length > 0, `${label} has no source`);
  for (const id of part.sources) {
    assert.ok(sourceIds.has(id), `${label} cites unknown source ${id}`);
  }
}

test("dataset: both founding counties are present with sourced frost dates and zones", () => {
  const ids = data.locations.map(l => l.id);
  assert.deepEqual(ids.sort(), ["lewis", "snohomish"]);
  for (const loc of data.locations) {
    assert.match(loc.lastSpringFrost, /^\d{2}-\d{2}$/);
    assert.match(loc.firstFallFrost, /^\d{2}-\d{2}$/);
    assert.ok(loc.frostFreeDays > 150 && loc.frostFreeDays < 260);
    assert.ok(loc.zones.length >= 1);
    assertSourced({ sources: loc.frostSources }, `${loc.id} frost dates`);
    assertSourced({ sources: loc.safeFrostSources }, `${loc.id} safe frost dates`);
    assertSourced({ sources: loc.zoneSources }, `${loc.id} zones`);
    assert.ok(loc.frostRangeNote.length > 40, `${loc.id} must carry its disagreement/range note`);
  }
  const lewis = data.locations.find(l => l.id === "lewis");
  assert.equal(lewis.lastSpringFrost, "04-22"); // Centralia, NOAA median
  assert.equal(lewis.safeLastSpringFrost, "04-30"); // Almanac 30% line
  const snohomish = data.locations.find(l => l.id === "snohomish");
  assert.equal(snohomish.lastSpringFrost, "03-24"); // Everett lowland, NOAA median
  assert.equal(snohomish.safeLastSpringFrost, "05-01"); // WSU observed latest since 2012
});

test("dataset: at least 30 crops, every window sourced, nothing invented", () => {
  assert.ok(data.crops.length >= 30, `expected >= 30 crops, got ${data.crops.length}`);
  const seen = new Set();
  for (const crop of data.crops) {
    assert.ok(crop.id && crop.name, "crop needs id and name");
    assert.ok(!seen.has(crop.id), `duplicate crop ${crop.id}`);
    seen.add(crop.id);
    assert.ok(FROST_CLASSES.has(crop.frostClass), `${crop.id} frost class`);
    assert.ok(
      crop.indoorStart || crop.transplant || crop.directSow || crop.fall,
      `${crop.id} has no window at all`
    );
    if (crop.indoorStart) {
      assertSourced(crop.indoorStart, `${crop.id} indoorStart`);
      const [a, b] = crop.indoorStart.weeksBeforeLastFrost;
      assert.ok(a >= 1 && b >= a && b <= 14, `${crop.id} indoor weeks sane`);
    }
    if (crop.transplant) {
      assertSourced(crop.transplant, `${crop.id} transplant`);
      if (crop.transplant.fixed) {
        assert.match(crop.transplant.fixed.start, /^\d{2}-\d{2}$/);
        assert.match(crop.transplant.fixed.end, /^\d{2}-\d{2}$/);
      } else {
        const [a, b] = crop.transplant.weeksFromLastFrost;
        assert.ok(b >= a && a >= -8 && b <= 8, `${crop.id} transplant weeks sane`);
      }
    }
    if (crop.directSow) {
      assertSourced(crop.directSow, `${crop.id} directSow`);
      const [a, b] = crop.directSow.weeksFromLastFrost;
      assert.ok(b >= a && a >= -8 && b <= 8, `${crop.id} sow weeks sane`);
    }
    if (crop.fall) {
      assertSourced(crop.fall, `${crop.id} fall`);
      assert.ok(crop.fall.text.length > 10, `${crop.id} fall needs its words`);
    }
    if (crop.daysToMaturity) {
      assertSourced(crop.daysToMaturity, `${crop.id} daysToMaturity`);
      assert.ok(crop.daysToMaturity.min <= crop.daysToMaturity.max);
      assert.ok(crop.daysToMaturity.min >= 20 && crop.daysToMaturity.max <= 200);
    }
  }
});

test("fixture: Lewis County, April 1 — broccoli goes out, radishes sow, tomatoes wait, frost watch open", () => {
  const advice = panel.adviceForDate(data, "lewis", "2027-04-01");
  assert.equal(advice.ok, true);
  assert.ok(advice.putOutNow.some(l => l.startsWith("Broccoli")), JSON.stringify(advice.putOutNow));
  assert.ok(advice.sowNow.some(l => l.startsWith("Radishes")), JSON.stringify(advice.sowNow));
  assert.ok(advice.tooEarly.some(l => l.startsWith("Tomatoes")), JSON.stringify(advice.tooEarly));
  assert.ok(advice.frostLines.length >= 1, "frost watch should be open on April 1 in Lewis County");
  assert.match(advice.frostLines[0], /cover tender plants tonight/);
});

test("fixture: Lewis County, February 1 — onions start indoors, peppers are coming", () => {
  const advice = panel.adviceForDate(data, "lewis", "2027-02-01");
  assert.ok(
    advice.startIndoorsNow.some(l => l.startsWith("Onions")),
    JSON.stringify(advice.startIndoorsNow)
  );
  assert.ok(advice.comingUp.some(l => l.startsWith("Peppers")), JSON.stringify(advice.comingUp));
});

test("fixture: Snohomish County, March 20 — potatoes sow, peas have passed, frost watch open", () => {
  const advice = panel.adviceForDate(data, "snohomish", "2027-03-20");
  assert.equal(advice.ok, true);
  assert.ok(advice.sowNow.some(l => l.startsWith("Potatoes")), JSON.stringify(advice.sowNow));
  assert.ok(!advice.sowNow.some(l => l.startsWith("Peas")), "pea window closed March 2 in Snohomish");
  assert.ok(advice.frostLines.length >= 1, "WSU's record keeps the watch open until May 1");
});

test("fixture: Lewis County, August 10 — fall broccoli is in, fall cabbage has closed", () => {
  const advice = panel.adviceForDate(data, "lewis", "2027-08-10");
  assert.ok(
    advice.sowNow.some(l => l.startsWith("Broccoli") && l.includes("fall")),
    JSON.stringify(advice.sowNow)
  );
  assert.ok(
    !advice.sowNow.some(l => l.startsWith("Cabbage")),
    "cabbage fall window closed August 1"
  );
  assert.equal(advice.frostLines.length, 0);
});

test("unknown county and bad date fail honestly", () => {
  assert.equal(panel.adviceForDate(data, "pierce", "2027-04-01").ok, false);
  assert.equal(panel.adviceForDate(data, "lewis", "not-a-date").ok, false);
});

test("moon layer: never generated, and labeled apart when a caller supplies it", () => {
  const plain = panel.adviceForDate(data, "lewis", "2027-04-01");
  assert.equal(plain.moonLayer, null);
  assert.ok(!panel.renderLines(plain).join("\n").includes("Codex layer"));

  const withMoon = panel.adviceForDate(data, "lewis", "2027-04-01", {
    moonLines: ["A caller-supplied moon line."]
  });
  assert.ok(withMoon.moonLayer);
  const lines = panel.renderLines(withMoon);
  const labelAt = lines.findIndex(l => l.includes("Codex layer"));
  const moonAt = lines.findIndex(l => l.includes("caller-supplied moon line"));
  assert.ok(labelAt > 0 && moonAt === labelAt + 1, "moon lines sit directly under their own label");
  const sourcesAt = lines.findIndex(l => l.startsWith("Sources:"));
  assert.ok(sourcesAt > 0 && sourcesAt < labelAt, "facts and their sources render before the moon layer");
});
